import{_ as e,o as t,c as r,a6 as s}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"stale-while-revalidate · 又快，又不太旧","description":"缓存 TTL 有个两难：设短了新鲜但常回源（慢），设长了快但容易旧。stale-while-revalidate 打破它——过期后先把旧的秒回给用户，同时后台悄悄更新。用户永远不等，缓存自动保鲜。这是 ISR 背后的核心机制。","frontmatter":{"title":"stale-while-revalidate · 又快，又不太旧","description":"缓存 TTL 有个两难：设短了新鲜但常回源（慢），设长了快但容易旧。stale-while-revalidate 打破它——过期后先把旧的秒回给用户，同时后台悄悄更新。用户永远不等，缓存自动保鲜。这是 ISR 背后的核心机制。","source":"https://daiw.org/manual/ssr/swr"},"headers":[],"relativePath":"manual/computer-programming/ssr/swr.md","filePath":"manual/computer-programming/ssr/swr.md"}'),l={name:"manual/computer-programming/ssr/swr.md"};function n(o,a,i,p,d,c){return t(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="stale-while-revalidate-·-又快-又不太旧" tabindex="-1">stale-while-revalidate · 又快，又不太旧 <a class="header-anchor" href="#stale-while-revalidate-·-又快-又不太旧" aria-label="Permalink to &quot;stale-while-revalidate · 又快，又不太旧&quot;">​</a></h1><p>缓存 TTL 有个两难：设短了新鲜但常回源（慢），设长了快但容易旧。stale-while-revalidate 打破它——过期后先把旧的秒回给用户，同时后台悄悄更新。用户永远不等，缓存自动保鲜。这是 ISR 背后的核心机制。</p><p><a href="/Front2Full/manual/computer-programming/ssr/why-cache">缓存的核心权衡</a> 落到 TTL 上，是个让人纠结的两难：</p><ul><li><strong>TTL 设短</strong>（比如 5 秒）：内容新鲜，但缓存<strong>频繁过期</strong>，过期就得回源渲染——命中率低、慢、还容易<a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">击穿</a>。</li><li><strong>TTL 设长</strong>（比如 1 小时）：命中率高、快、扛量强，但用户可能看到<strong>一小时前的旧数据</strong>。</li></ul><p>有没有办法<strong>两头都要</strong>？有——这就是 <strong><code>stale-while-revalidate</code></strong>（简称 SWR）。它是本专栏最该记牢的一个机制。</p><h2 id="核心思想-先给旧的-后台更新" tabindex="-1">核心思想：先给旧的，后台更新 <a class="header-anchor" href="#核心思想-先给旧的-后台更新" aria-label="Permalink to &quot;核心思想：先给旧的，后台更新&quot;">​</a></h2><p>SWR 的洞见极其朴素：<strong>当缓存过期时，与其让用户干等着「重新渲染」，不如先把手边的旧版本给他（他几乎不在乎差这几秒），同时在后台悄悄地把缓存更新掉。</strong></p><p>于是<strong>用户永远拿的是缓存（快），而缓存永远在后台自我保鲜（不太旧）</strong>。回源渲染这件慢事，被挪到了「后台」，不再挡在用户和响应之间。</p><h2 id="三个阶段" tabindex="-1">三个阶段 <a class="header-anchor" href="#三个阶段" aria-label="Permalink to &quot;三个阶段&quot;">​</a></h2><p><code>Cache-Control: max-age=60, stale-while-revalidate=300</code> 把缓存的一生分成三段：</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R[&quot;请求到达,看缓存年龄&quot;] --&gt; A{&quot;处于哪一段&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A --&gt;|&quot;新鲜期(0~60 秒)&quot;| B[&quot;直接给缓存&lt;br/&gt;源站零打扰&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A --&gt;|&quot;SWR 窗口(60~360 秒)&quot;| C[&quot;立刻给旧的(用户不等)&lt;br/&gt;+ 后台回源,悄悄更新缓存&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A --&gt;|&quot;超出窗口(360 秒后)&quot;| D[&quot;阻塞回源&lt;br/&gt;拿到新的再返回&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li><strong>0~60 秒（新鲜）</strong>：直接给缓存，连「变了没」都不问。最理想。</li><li><strong>60~360 秒（SWR 窗口）</strong>：缓存过期了，但还在 <code>stale-while-revalidate</code> 的宽限期内。<strong>立刻把旧的返回给用户</strong>（用户体验和命中一样快），<strong>同时</strong>触发一次后台回源更新缓存。下一个请求就能拿到新的。</li><li><strong>360 秒之后（太旧）</strong>：超出宽限期，旧的不能再用了，只能<strong>老老实实阻塞回源</strong>——这个请求要等渲染完（慢的那种）。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>关键在中间那段：用户拿到旧内容的速度，和命中缓存一样快——他完全不必等待那次后台更新。</strong> 更新是「顺便」发生的，发生在别人（或后台）身上，不挡这个用户的路。于是绝大多数请求都落在「新鲜」或「SWR 窗口」里，几乎<strong>永远不触发那个慢的阻塞回源</strong>。你既拿到了接近长 TTL 的速度与扛量，又拿到了「最多旧几分钟、且在自动变新」的新鲜度。</p></div><h2 id="它顺手治了缓存击穿" tabindex="-1">它顺手治了缓存击穿 <a class="header-anchor" href="#它顺手治了缓存击穿" aria-label="Permalink to &quot;它顺手治了缓存击穿&quot;">​</a></h2><p>回想<a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">上一章</a> 那个「过期瞬间千军万马同时回源」的<strong>缓存击穿</strong>。SWR 天然免疫它：过期后大家拿的是<strong>旧缓存</strong>（不回源），后台只需<strong>一个</strong>更新请求去回源。<strong>尖峰被抹平了</strong>——没有「同时回源」这回事。这是 SWR 除了「快 + 新鲜」之外的第三个好处。</p><h2 id="搭档-stale-if-error" tabindex="-1">搭档：stale-if-error <a class="header-anchor" href="#搭档-stale-if-error" aria-label="Permalink to &quot;搭档：stale-if-error&quot;">​</a></h2><p>和 SWR 成对的还有 <strong><code>stale-if-error</code></strong>：<strong>当源站出错(5xx)或挂掉时，拿旧缓存顶上，别给用户报错。</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: max-age=60, stale-while-revalidate=300, stale-if-error=86400</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这一句给了你一天（86400 秒）的「灾备缓冲」：哪怕源站彻底宕机，只要 CDN 里还有一天内的旧版本，用户看到的仍是<strong>能用的旧页面</strong>，而不是 502。对可用性来说，这是一层极其廉价的保险。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>SWR 不是万能——它的前提是「用户能容忍看到旧内容」。</strong> 对博客、商品详情、榜单这类，旧几分钟无所谓，SWR 完美。但对<strong>必须实时</strong>的东西（账户余额、库存精确到件、下单确认），「先给旧的」可能是错的——用户不能接受看到已经不对的余额。<strong>SWR 用「一点点陈旧」换「快 + 扛量 + 抗击穿」，所以只适合能付这个学费的内容。</strong> 实时性要求高的，要么不缓存，要么用<a href="/Front2Full/manual/computer-programming/ssr/cache-invalidation">按需失效</a>在数据一变就精准刷新。</p></div><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p><code>stale-while-revalidate</code> 用「过期后先给旧的、后台再更新」破解了 TTL 两难：用户永远快（拿缓存），缓存永远在自我保鲜（后台更新），还顺手免疫了缓存击穿；配 <code>stale-if-error</code> 更添一层灾备。前提是内容能容忍短暂陈旧。</p><p>这个「先返回预生成的旧版本、后台按需重新生成」的机制，如果把它从「CDN 层的 HTTP 缓存」上升到「框架层的页面生成策略」，就变成了一个响当当的名字——<strong>增量静态再生(ISR)</strong>。它是 SSG 和 SSR 之间那个甜蜜的中间态。下一章讲透。👉 <a href="/Front2Full/manual/computer-programming/ssr/isr">增量静态再生：SSG 与 SSR 的中间态</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] RFC 5861.「HTTP Cache-Control Extensions for Stale Content.」<a href="https://datatracker.ietf.org/doc/html/rfc5861" target="_blank" rel="noreferrer">https://datatracker.ietf.org/doc/html/rfc5861</a> —— <code>stale-while-revalidate</code> / <code>stale-if-error</code> 的规范。</li><li>[2] web.dev.「Keeping things fresh with stale-while-revalidate.」<a href="https://web.dev/articles/stale-while-revalidate" target="_blank" rel="noreferrer">https://web.dev/articles/stale-while-revalidate</a> —— SWR 实战。</li><li>[3] MDN.「Cache-Control — stale-while-revalidate.」<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control</a> —— 指令定义。</li></ul>`,25)])])}const u=e(l,[["render",n]]);export{g as __pageData,u as default};
